<template><section><header class="toolbar"><slot name="toolbar"/><el-button v-if="selectable" :disabled="!selected.length" @click="$emit('batch',selected)">批量操作</el-button></header><el-table :data="visible" stripe border @selection-change="selected=$event"><el-table-column v-if="selectable" type="selection" width="48"/><el-table-column v-for="c in columns" :key="c.prop" :prop="c.prop" :label="c.label" :width="c.width"/><slot/></el-table><el-pagination v-model:current-page="page" :page-size="pageSize" @current-change="$emit('page-change',$event)" class="pager" background layout="total, prev, pager, next" :total="total"/></section></template>
<script setup>
import{ref,computed,watch}from'vue';const props=defineProps({data:{type:Array,required:true},columns:{type:Array,required:true},total:{type:Number,default:0},selectable:{type:Boolean,default:true},pageSize:{type:Number,default:10}});defineEmits(["batch","page-change"]);const selected=ref([]);const page=ref(1);const visible=computed(()=>props.total>props.data.length?props.data:props.data.slice((page.value-1)*props.pageSize,page.value*props.pageSize));watch(()=>props.data,()=>{page.value=1;selected.value=[]});
</script>
<style lang="less" scoped>.toolbar{display:flex;justify-content:space-between;margin-bottom:var(--space-12)}.pager{justify-content:flex-end;margin-top:var(--space-16)}</style>
